#!/usr/bin/env node
/**
 * Tests for hooks/read-guard.js. Zero dependencies — `node:test` on Node 18+.
 *
 *   node --test tools/read-guard.test.mjs
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const HOOK = join(dirname(fileURLToPath(import.meta.url)), '..', 'hooks', 'read-guard.js');
const root = mkdtempSync(join(tmpdir(), 'read-guard-'));

const file = (rel, bytes) => {
  const path = join(root, rel);
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, 'x'.repeat(bytes));
  return path;
};
const read = (tool_input) => {
  const r = spawnSync(process.execPath, [HOOK], {
    input: JSON.stringify({ hook_event_name: 'PreToolUse', tool_name: 'Read', tool_input }),
    encoding: 'utf8',
  });
  assert.equal(r.status, 0);
  return r.stdout ? JSON.parse(r.stdout).hookSpecificOutput : null;
};

const persisted = file('Temp/claude/abc/sess/tool-results/out.txt', 40_000);
const transcript = file('.claude/projects/C--repo/sess.jsonl', 2_000);
const big = file('src/big.log', 300 * 1024);
const projectOutput = file('.claude/projects/C--repo/sess/tool-results/b1.txt', 30_000);

test('a whole read of a persisted output, a transcript or a big file is denied, pointing at Grep or a range', () => {
  for (const file_path of [persisted, transcript, big, projectOutput]) {
    const d = read({ file_path });
    assert.equal(d?.permissionDecision, 'deny', file_path);
    assert.match(d.permissionDecisionReason, /Grep it for what you need/);
    assert.match(d.permissionDecisionReason, /offset and limit/);
  }
  assert.match(read({ file_path: big }).permissionDecisionReason, /a 300 KB file/);
});

test('a ranged read, allow_large, a small file, the scratchpad, an image or a missing file pass', () => {
  assert.equal(read({ file_path: persisted, offset: 1, limit: 50 }), null);
  assert.equal(read({ file_path: transcript, limit: 20 }), null);
  assert.equal(read({ file_path: big, allow_large: true }), null);
  assert.equal(read({ file_path: file('src/small.cs', 5_000) }), null);
  assert.equal(read({ file_path: file('Temp/claude/abc/sess/scratchpad/notes.md', 40_000) }), null);
  assert.equal(read({ file_path: file('shots/page.png', 600 * 1024) }), null);
  assert.equal(read({ file_path: join(root, 'missing.txt') }), null);
});

test('a bad payload lets the read through', () => {
  const r = spawnSync(process.execPath, [HOOK], { input: 'not json', encoding: 'utf8' });
  assert.equal(r.status, 0);
  assert.equal(r.stdout, '');
});
